import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Retro: honest promotion — the admitted objects, audited for the library","description":"","frontmatter":{"title":"Retro: honest promotion — the admitted objects, audited for the library","type":"retro","date":"2026-10-05T00:00:00.000Z"},"headers":[],"relativePath":"graphopt/project/retros/promoted-laws.md","filePath":"vendored/graphopt/project/retros/promoted-laws.md"}`),a={name:`graphopt/project/retros/promoted-laws.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="retro-honest-promotion-—-the-admitted-objects-audited-for-the-library" tabindex="-1">Retro: honest promotion — the admitted objects, audited for the library <a class="header-anchor" href="#retro-honest-promotion-—-the-admitted-objects-audited-for-the-library" aria-label="Permalink to “Retro: honest promotion — the admitted objects, audited for the library”">​</a></h1><p>Context: follow-up to plan 0017 / the admission-gauntlet and auto-cond rounds. The store now holds a dozen objects that cleared the gauntlet — reconstruct, full-data, measure, truth, novelty, typed-pay, closure, cert all green. That is <em>admission</em>, not promotion: the gauntlet proves an object is sound, paying and serializable on the measured domain, but it does not decide whether the object is a law the library lacks, a respelling of one it has, or corpus-specific material that should not ship. This retro records that call.</p><p>Promoted code lives in <code>mlopt_core.laws.tensor</code>; nothing under <code>mlopt_discovery</code> changed (<code>oracle.py</code>/<code>evidence.py</code>/<code>intake.py</code>/ <code>opmeta</code>/<code>opdata</code> untouched).</p><h2 id="the-rule" tabindex="-1">The rule <a class="header-anchor" href="#the-rule" aria-label="Permalink to “The rule”">​</a></h2><p>For each admitted object: <strong>(a)</strong> a genuine library addition — a law the library lacks that fires on real modules, pays, and is clean on its declared region; <strong>(b)</strong> duplicate/subsumed — an existing law already covers it (or a strictly more general law does); <strong>(c)</strong> not worth shipping — corpus-specific, no pay, or no clean region.</p><h2 id="promotion-table" tabindex="-1">Promotion table <a class="header-anchor" href="#promotion-table" aria-label="Permalink to “Promotion table”">​</a></h2><table tabindex="0"><thead><tr><th>object</th><th>verdict</th><th>shipped as</th><th>evidence</th></tr></thead><tbody><tr><td><code>softsign_fold</code></td><td><strong>promoted</strong></td><td><code>softsign_fold</code></td><td><code>div(x, abs(x)+1) → softsign(x)</code>; unguarded, 3 ops → 1 kernel; sweep 17/17 equal; fires the <code>nn.Softsign</code> intake spelling</td></tr><tr><td><code>sdpa_fold_nomask</code></td><td><strong>promoted</strong></td><td><code>sdpa_fold_nomask</code></td><td>mask-free <code>matmul(softmax(q·kᵀ), v)</code> — the <code>nn.MultiheadAttention</code> default path the <code>add</code>/<code>masked_fill</code> family never matched; generalized to the family guard (<code>_COND_SDPA_BASE</code>) plus the measured <code>rank(Q,V) &gt;= 2</code> floor (rank-1 <code>Q</code> mints a non-denoting <code>sdpa</code> — <code>rhs-err</code>)</td></tr><tr><td><code>sdpa_fold_div_nomask</code></td><td><strong>promoted</strong></td><td><code>sdpa_fold_div_nomask</code></td><td>same, with <code>div</code>-by-<code>S</code> scale; <code>dspec</code> mints <code>scale = 1/S</code>; guard is <code>_COND_SDPA_SCALED ∧ rank(Q,V) ≥ 2</code></td></tr><tr><td><code>sdpa_fold_div_nomask_g</code></td><td><strong>subsumed</strong></td><td>(folded into <code>sdpa_fold_div_nomask</code>)</td><td>the <code>_g</code> twin&#39;s metavar-axes pattern IS the promoted rule; its minted guard is the same last-two-axes fact the family carries — no separate spelling needed</td></tr><tr><td><code>mul_unsqueeze_l_id</code></td><td><strong>promoted</strong></td><td><code>mul_unsq_pad_l</code></td><td>first inhabitant; <code>bcast-eq ∧ bcast-into</code> region (≡ <code>ones-before ∧ bcast-eq</code>); sweep 23/23 equal, corpus pays on the ALiBi pad spelling</td></tr><tr><td><code>mul_unsqueeze_r_id</code></td><td><strong>promoted</strong></td><td><code>mul_unsq_pad_r</code></td><td>right-operand twin; sweep 23/23 equal</td></tr><tr><td><code>sub_unsqueeze_l_id</code></td><td><strong>promoted</strong></td><td><code>sub_unsq_pad_l</code></td><td>same pad region under <code>sub</code> — the asymmetric op proves the guard, not commutativity, carries it</td></tr><tr><td><code>mul_reshape_l_id</code></td><td><strong>promoted</strong></td><td><code>mul_reshape_inert_l</code></td><td>single-clause <code>bcast-eq(reshape-out(u,S), v, u, v)</code>; equal grids force a 1-axis insert/remove — a permuting reshape changes an extent and the grids disagree; sweep 60/60 equal</td></tr><tr><td><code>mul_transpose_l_id</code></td><td><strong>subsumed</strong></td><td><code>transpose_noop</code></td><td>the honest law is the <em>view-identity</em> itself: <code>transpose(u, d0, d1) → u</code> under <code>axes-noop</code>; once the transpose merges into <code>u</code>&#39;s e-class, congruence does the mul/add strip in every context</td></tr><tr><td><code>add_transpose_l_id</code></td><td><strong>subsumed</strong></td><td><code>transpose_noop</code></td><td>same — the wrapped spellings stay store objects</td></tr><tr><td><code>mul_chunk_l_id</code></td><td><strong>subsumed</strong></td><td><code>chunk_single</code></td><td><code>chunk(u, chunks=1, d, i) → u</code> under <code>attr-eq(C, 1)</code> — the single-chunk partition IS the tensor; the mul-wrapped strip follows by congruence</td></tr><tr><td><code>linear_channel_scale_rev ∘ linear_row_scale</code></td><td><strong>promoted</strong></td><td><code>linear_channel_to_row_scale</code></td><td>derivable composite, <code>derivation=(&quot;linear_channel_scale_rev&quot;, &quot;linear_row_scale&quot;)</code>, kind <code>lemma</code>; both premises are SYMMETRY-gated (opt-in), so under <code>DEFAULT</code> this term-local edge is genuinely new reach; transported guard is the premises&#39; conjunction over the shared <code>c</code>; paid 1 on corpus</td></tr><tr><td><code>om_lift</code></td><td><strong>duplicate — rejected</strong></td><td>—</td><td><code>mlopt_carriers.om.OM_LIFT</code>/<code>om_lift_plain</code> already ship <code>matmul(softmax(s,d), v) → om_apply(om_elem(s,v))</code> with the metavar-dim guard; the constructed literal <code>dim=-1</code> pattern is a strict subset</td></tr><tr><td><code>affd_step_lift</code></td><td><strong>duplicate — rejected</strong></td><td>—</td><td>alpha-identical to the shipped <code>affd_lift</code> (<code>SCAN_DIAG_LAWS</code>): same <code>add(mul(a,h),x) → applyd(aff_diag(a,x),h)</code>, same <code>_COND_AFFD_STATE</code></td></tr><tr><td><code>affd_scan2_lift</code></td><td><strong>rejected — derivable unroll</strong></td><td>—</td><td>two <code>affd_lift</code> firings already produce exactly this member under <code>SCAN_DIAG_LAWS</code> saturation; a fixed-arity-2 shortcut is corpus-depth-shaped, not a law</td></tr><tr><td><code>affd_scan4_lift</code></td><td><strong>rejected — derivable unroll</strong></td><td>—</td><td>same at arity 4 — the corpus&#39;s 4-deep <code>DiagonalSSM</code> spines are why it paid; arity-specific composites are not library axioms</td></tr></tbody></table><h2 id="what-the-promotion-changed" tabindex="-1">What the promotion changed <a class="header-anchor" href="#what-the-promotion-changed" aria-label="Permalink to “What the promotion changed”">​</a></h2><p><code>ALL_RULES</code> 61 → <strong>71</strong> (<code>SIMPLIFICATION_RULES</code> 23 → 30, <code>CATEGORICAL_RULES</code> 38 → 41, <code>SDPA_FOLD_RULES</code> 12 → 14).</p><ul><li>Declared split: 55 axioms / 14 lemmas / 2 redundant (the composite is the new lemma; the other nine promotions are axioms).</li><li>Serialization census: <strong>71/71 full-data</strong> — every promoted law is pure pattern + <code>cond</code>/<code>dspec</code>/<code>derivation</code> data; <code>missing_hooks == ()</code> throughout. The hook-free (no <code>check</code>, no <code>derive</code>) count rose 24 → 25 (<code>softsign_fold</code> is unguarded).</li><li><code>cond</code> users: 36 → <strong>45</strong>; <code>dspec</code> users: 16 → <strong>18</strong>.</li><li><code>FUSION</code>-tagged: 17 → <strong>19</strong> (the two <code>sdpa</code> nomask folds).</li><li>Measured coherence (<code>--emit-basis</code>): 47 axioms / 13 lemmas / 2 redundant / <strong>9 no-instance</strong> — the promoted conditional laws the catalogue&#39;s instancer cannot build a concrete site for (they are shape-guarded, not corpus-spelled); <code>linear_channel_to_row_scale</code> among them — its derivation is declared and store-certified, the catalogue just found no instance to replay it on.</li></ul><h2 id="guards-—-what-the-promoted-laws-carry" tabindex="-1">Guards — what the promoted laws carry <a class="header-anchor" href="#guards-—-what-the-promoted-laws-carry" aria-label="Permalink to “Guards — what the promoted laws carry”">​</a></h2><ul><li><code>transpose_noop</code>: <code>(&quot;axes-noop&quot;, &quot;u&quot;, &quot;D0&quot;, &quot;D1&quot;)</code> — swap axes coincide mod rank, or both swapped extents are 1.</li><li><code>chunk_single</code>: <code>(&quot;attr-eq&quot;, &quot;CK&quot;, 1)</code> — one section is the tensor.</li><li><code>mul_unsq_pad_{l,r}</code> / <code>sub_unsq_pad_l</code>: the auto-derived pair <code>bcast-eq(unsq-out(t,UD), other, t, other) ∧ bcast-into(t, unsq-out(t,UD))</code> — grid coincidence plus &quot;the operand fits its own padded shape&quot; (which collapses to <code>ones-before</code> on shapes).</li><li><code>mul_reshape_inert_l</code>: <code>bcast-eq(reshape-out(u,RS), v, u, v)</code> — broadcast-grid equality alone, exactly as minted.</li><li><code>sdpa_fold_nomask</code> / <code>sdpa_fold_div_nomask</code>: the family guard (<code>_COND_SDPA_BASE</code> / <code>_COND_SDPA_SCALED</code>) plus <code>rank(Q) ≥ 2 ∧ rank(V) ≥ 2</code> — <code>sdpa</code> needs rank ≥ 2 operands and the mask-free LHS still denotes on a rank-1 <code>Q</code>/<code>V</code>; <code>K</code>&#39;s floor is implied by <code>axes-last2</code>. (The masked family gets away without the clause — the mask operand&#39;s read makes a rank-1 <code>Q</code> lhs fail anyway; a latent guard-residual worth noting.)</li><li><code>linear_channel_to_row_scale</code>: the transported conjunction <code>(&quot;and&quot;, _COND_CHANNEL_SCALE, _COND_ROW_SCALE_c)</code> — the scalar <code>c</code> corner satisfies both sides.</li></ul><h2 id="sweeps-re-measured-at-promotion" tabindex="-1">Sweeps re-measured at promotion <a class="header-anchor" href="#sweeps-re-measured-at-promotion" aria-label="Permalink to “Sweeps re-measured at promotion”">​</a></h2><p>Each promoted rule was re-run through <code>_guarded_evals</code> over <code>_synth_sites</code> (360-site window) plus a real-site firing check (<code>EGraph.run</code> → merged e-class on the corpus spelling, decline on an off-region binding):</p><table tabindex="0"><thead><tr><th>law</th><th>accepted</th><th>equal</th><th>unequal</th><th>rhs_err</th><th>fires</th></tr></thead><tbody><tr><td><code>softsign_fold</code></td><td>17</td><td>17</td><td>0</td><td>0</td><td><code>div(x,abs(x)+1)</code> → <code>softsign</code></td></tr><tr><td><code>transpose_noop</code></td><td>7</td><td>7</td><td>0</td><td>0</td><td><code>(2,1,1).transpose(-2,-1)</code></td></tr><tr><td><code>chunk_single</code></td><td>12</td><td>12</td><td>0</td><td>0</td><td><code>chunk(u,1,-1,0)</code></td></tr><tr><td><code>mul_unsq_pad_l</code></td><td>23</td><td>23</td><td>0</td><td>0</td><td><code>mul(unsq(u,0),(1,1,1))</code></td></tr><tr><td><code>mul_unsq_pad_r</code></td><td>23</td><td>23</td><td>0</td><td>0</td><td><code>mul((1,8,8),unsq(v,0))</code></td></tr><tr><td><code>sub_unsq_pad_l</code></td><td>23</td><td>23</td><td>0</td><td>0</td><td><code>sub(unsq(u,0),(1,1,1))</code></td></tr><tr><td><code>mul_reshape_inert_l</code></td><td>60</td><td>60</td><td>0</td><td>0</td><td><code>(2,6)→(1,2,6)</code> pad</td></tr><tr><td><code>sdpa_fold_nomask</code></td><td>7</td><td>6</td><td>0</td><td>0</td><td>spelled attention → <code>sdpa</code></td></tr><tr><td><code>sdpa_fold_div_nomask</code></td><td>3</td><td>3</td><td>0</td><td>0</td><td>scaled spelling → <code>sdpa(…,scale=1/s)</code></td></tr><tr><td><code>linear_channel_to_row_scale</code></td><td>19</td><td>19</td><td>0</td><td>0</td><td><code>linear(x, W·c)</code> → <code>c·linear(x,W)</code></td></tr></tbody></table><h2 id="test-fallout-—-the-honest-post-promotion-state" tabindex="-1">Test fallout — the honest post-promotion state <a class="header-anchor" href="#test-fallout-—-the-honest-post-promotion-state" aria-label="Permalink to “Test fallout — the honest post-promotion state”">​</a></h2><p>Promoting a pattern makes the <em>stored object</em> a library duplicate (<code>relation</code> keys on the <code>(lhs, rhs)</code> alpha pair — <code>cond</code> is not part of the key). The store&#39;s novelty gate now reports:</p><ul><li><code>mul_unsqueeze_l_id</code>, <code>sub_unsqueeze_l_id</code>, <code>mul_reshape_l_id</code> → <code>duplicate</code> (alpha-equal to <code>mul_unsq_pad_l</code>, <code>sub_unsq_pad_l</code>, <code>mul_reshape_inert_l</code>);</li><li><code>softsign_fold</code> → <code>duplicate</code>;</li><li><code>channel_then_row_scale</code> → <code>duplicate</code> (same pattern as <code>linear_channel_to_row_scale</code>);</li><li><code>mul_unsqueeze_r_id</code> stays <code>new</code> — the record&#39;s rhs is <code>mul(v, u)</code>, the shipped law&#39;s is <code>mul(u, v)</code>;</li><li><code>mul_transpose_l_id</code>, <code>add_transpose_l_id</code>, <code>mul_chunk_l_id</code> stay <code>new</code> — only the <em>generic</em> view identities shipped, not the wrapped strips;</li><li>the <code>sdpa</code> objects stay <code>new</code> — the promoted rules carry metavar attrs (<code>dim=&quot;SD&quot;</code>, <code>scale=&quot;SC&quot;</code>) where the records pin literals;</li><li><code>affd_*</code> / <code>om_lift</code> stay <code>new</code> — <code>SCAN_DIAG_LAWS</code> and <code>OM_LAWS</code> are not in <code>ALL_RULES</code> (the novelty library), so the duplicate verdict rests on this audit, not the alpha-key check.</li></ul><p>Gauntlet tests that pinned a now-shipped object&#39;s <code>usable</code> verdict were repointed at still-unshipped admitted siblings (<code>mul_transpose_l_id</code>, <code>add_unsqueeze_l_id</code>) and one new test pins the duplicate verdict itself (<code>test_promoted_object_now_reports_library_duplicate</code>).</p><h2 id="limitations-follow-ups" tabindex="-1">Limitations / follow-ups <a class="header-anchor" href="#limitations-follow-ups" aria-label="Permalink to “Limitations / follow-ups”">​</a></h2><ul><li>The <code>add</code>/<code>div</code>/<code>getitem</code>-wrapped unsqueeze strips and the dropout-wrapped <code>sdpa_fold_nomask</code> form are natural siblings that were <strong>not</strong> measured — deliberately left unshipped rather than extrapolated.</li><li><code>mul_unsq_pad_l</code>&#39;s shipped guard is the auto-cond pair (<code>bcast-eq ∧ bcast-into</code>), semantically the <code>ones-before ∧ bcast-eq</code> region the first inhabitant carried. The minted clause is the measured one; <code>ones-before</code> would read clearer but the promotion rule is &quot;the auto-derived guard, verbatim&quot;.</li><li>The shipped <code>sdpa_fold_add*</code>/<code>masked_fill*</code> family carries a latent <code>rank(Q) ≥ 2</code> blind spot the nomask promotions needed explicitly — masked sites mask it because the lhs fails to denote there. A guard-residuals tightening candidate, not promoted-rule scope.</li><li>Pre-existing (uncommitted, pre-dating this work) <code>oracle.py</code> enumeration changes shift three discovery-test pins (<code>test_guarded_truth_sweep_counts</code> 23→26 equal, <code>test_sdpa_fold_addmul_region_appears_at_the_guarded_cap</code> one rhs-err at the grown window, <code>test_auto_cond_g_twin_the_attr_case</code> mints <code>axis(V,TD2,-1)</code> for the <code>_g</code> twin) and two <code>test_discovery_oracle</code> index pins (<code>_first_equal_index</code> 327→337, <code>_reshape_targets</code> dedup) — unrelated to the promoted laws; the enumeration WIP owns those.</li></ul>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};